'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var dlasq5 = require( './../lib/' );

var Z = new Float64Array([ 6, 0, 3, 0, 8, 0, 2, 0, 10, 0, 4, 0, 18, 0, 0, 0 ]);
var out = new Float64Array( 6 );

// Parameters:
var I0 = 0;
var N0 = 3;
var PP = 0;
var TAU = 0.25;
var SIGMA = 0.0;
var IEEE = true;
var EPS = 2.220446049250313e-16;

dlasq5( I0, N0, Z, PP, TAU, SIGMA, IEEE, EPS, out );
console.log( 'Ping:', out );

Z = new Float64Array( [ 6, 0, 3, 0, 8, 0, 2, 0, 10, 0, 4, 0, 18, 0, 0, 0 ] );
PP = 1;

dlasq5.ndarray( I0, N0, Z, 1, 0, PP, TAU, SIGMA, IEEE, EPS, out, 1, 0 );
console.log( 'Pong:', out );
